// ===== باقي الدوال - كلها window. عشان الأزرار تشتغل =====
window.getSecureRules = function(){ return '{\n "rules": {\n  "users": {"$uid": {".read": "auth != null", ".write": "auth != null"}},\n  "depositRequests": {".read": "auth != null", ".write": "auth != null"},\n  "captainRequests": {".read": "auth != null", ".write": "auth != null"},\n  "trips": {".read": "auth != null", ".write": "auth != null"}\n }\n}'; };
window.copySecureRules = function(){ var r=window.getSecureRules(); if(navigator.clipboard) navigator.clipboard.writeText(r).then(function(){alert('✅ اتنسخت Rules');}); else prompt('انسخ:',r); };
window.testFirebaseConnection = function(){ fbDB.ref('_test/ping').set({time:new Date().toISOString()}).then(function(){alert('✅ Firebase شغال - tawsila-37a80'); if(el('firebaseStatusTxt')) el('firebaseStatusTxt').innerText='✅ متصل آمن - tawsila-37a80';}).catch(function(e){alert('❌ '+e.message);}); };
window.syncAllToFirebase = function(){ var users=getUsers(); users.forEach(function(u){ var c={}; for(var k in u){ if(k!=='pass') c[k]=u[k]; } fbSet('users/'+u.id,c); }); alert('✅ تم مزامنة '+users.length+' مستخدم'); };
window.addEventListener('beforeinstallprompt',function(e){ e.preventDefault(); _deferredPrompt=e; });
window.installApp = function(){ if(_deferredPrompt){ _deferredPrompt.prompt(); } else alert('📱 عشان تثبت التطبيق:\n- أندرويد: دوس ⋮ > Add to Home Screen\n- آيفون: مشاركة > Add to Home Screen'); };
window.downloadAPK = function(){ var url=prompt('حط رابط APK من Google Drive:','https://drive.google.com/file/d/YOUR_APK_ID/view'); if(url && url.indexOf('YOUR_APK_ID')===-1){ window.open(url,'_blank'); } else if(url){ alert('⚠️ حط رابط APK الحقيقي مكان YOUR_APK_ID'); } };
function startFirebaseListeners(){
  try{
    fbDB.ref('depositRequests').on('value',function(s){ var v=s.val()||{}; saveLS('TAWSILA_DEPOSIT_REQUESTS',Object.values(v)); if(el('view-admin') && !el('view-admin').classList.contains('hidden')) window.renderDepositRequests(); window.renderMyDepositRequests(); });
    fbDB.ref('captainRequests').on('value',function(s){ if(el('view-admin') && !el('view-admin').classList.contains('hidden')) window.renderCaptainRequests(); });
    fbDB.ref('users').on('value',function(s){ var v=s.val()||{}; var list=Object.values(v); if(list.length>0){ var local=getUsers(); list.forEach(function(fu){ var l=null; for(var i=0;i<local.length;i++){ if(local[i].id===fu.id) l=local[i]; } if(l) fu.pass=l.pass; }); saveUsers(list); } });
    if(el('firebaseStatusTxt')) el('firebaseStatusTxt').innerText='✅ متصل آمن - tawsila-37a80 - RTDB Live 🔒';
  }catch(e){ if(el('firebaseStatusTxt')) el('firebaseStatusTxt').innerText='⚠️ '+e.message; }
}
window.navigate = function(view){ var views=['view-auth','view-customer','view-driver','view-admin']; for(var i=0;i<views.length;i++){ if(el(views[i])) el(views[i]).classList.add('hidden'); } if(el('view-'+view)) el('view-'+view).classList.remove('hidden'); if(view==='customer'){ window.updateWalletUI(); window.recalcTrip(); window.renderMyDepositRequests(); if(el('myReferralCodeTxt')) el('myReferralCodeTxt').innerText=window.getMyReferralCode(); } if(view==='admin'){ window.renderProfitDashboard(); window.renderDepositRequests(); window.renderCaptainRequests(); window.renderAdminUsers(); window.renderAdminTrips(); } if(view==='driver' && el('captainWalletTxt')) el('captainWalletTxt').innerText=(DB.captainWallet||0)+' ج.م'; window.scrollTo(0,0); };
window.setSession = function(u){ saveLS('TAWSILA_SESSION',u); };
window.logout = function(){ saveLS('TAWSILA_SESSION',null); try{ fbAuth.signOut(); }catch(e){} window.navigate('auth'); };
window.switchAuthTab = function(t){ if(el('auth-login-form')) el('auth-login-form').classList.toggle('hidden',t!=='login'); if(el('auth-register-form')) el('auth-register-form').classList.toggle('hidden',t!=='register'); };
window.updateWalletUI = function(){ if(el('walletBalance')) el('walletBalance').innerText=(DB.customerWallet||0).toFixed(2)+' ج.م'; };
window.requestPushPermission = function(){ if(!('Notification' in window)) return alert('متصفحك مش بيدعم'); Notification.requestPermission().then(function(p){ if(p==='granted'){ alert('✅ الإشعارات اتفعلت'); } }); };
window.sendPush = function(t,b){ if('Notification' in window && Notification.permission==='granted' && document.hidden) new Notification(t,{body:b}); };
window.hashImage = function(d){ var h=0; for(var i=0;i<d.length;i+=100) h=(h*31+d.charCodeAt(i))|0; return 'h'+h+'_'+d.length; };
window.toggleCaptainDocs = function(s){ if(el('captainDocsSection')) el('captainDocsSection').classList.toggle('hidden',!s); };
window.previewDoc = function(input,pid){ var f=input.files[0]; if(!f) return; if(f.size>3*1024*1024){ alert('❌ الصورة كبيرة'); input.value=''; return; } var r=new FileReader(); r.onload=function(e){ var img=new Image(); img.onload=function(){ var c=document.createElement('canvas'); var sc=Math.min(1,800/img.width); c.width=img.width*sc; c.height=img.height*sc; c.getContext('2d').drawImage(img,0,0,c.width,c.height); var comp=c.toDataURL('image/jpeg',0.7); captainDocsData[pid.replace('prev_','')]=comp; var p=el(pid); if(p){ p.src=comp; p.classList.remove('hidden'); } }; img.src=e.target.result; }; r.readAsDataURL(f); };
function getCaptainDocsFromForm(){ return {idFront:captainDocsData['idFront']||'',idBack:captainDocsData['idBack']||'',vehicleFront:captainDocsData['vehicleFront']||'',vehicleBack:captainDocsData['vehicleBack']||'',driveFront:captainDocsData['driveFront']||'',driveBack:captainDocsData['driveBack']||''}; }
function validateCaptainDocs(d,v){ if(!d.idFront) return 'ارفع وش البطاقة'; if(!d.idBack) return 'ارفع ضهر البطاقة'; if(!d.vehicleFront) return 'ارفع وش رخصة المركبة'; if(!d.vehicleBack) return 'ارفع ضهر رخصة المركبة'; if(!d.driveFront) return 'ارفع وش رخصة القيادة'; if(!d.driveBack) return 'ارفع ضهر رخصة القيادة'; if(!v.type) return 'اختار نوع المركبة'; if(!v.model) return 'اكتب الموديل'; if(!v.year) return 'اكتب سنة الصنع'; if(!v.color) return 'اكتب اللون'; if(!v.plate) return 'اكتب رقم اللوحة'; if(!v.chassis) return 'اكتب رقم الشاسيه'; return null; }
async function uploadToFirebase(dataUrl,path){ try{ var arr=dataUrl.split(','); var mime=arr[0].match(/:(.*?);/)[1]; var bstr=atob(arr[1]); var u8=new Uint8Array(bstr.length); for(var i=0;i<bstr.length;i++) u8[i]=bstr.charCodeAt(i); var blob=new Blob([u8],{type:mime}); var ref=fbStorage.ref(path+'/'+Date.now()+'.jpg'); var snap=await ref.put(blob); return await snap.ref.getDownloadURL(); }catch(e){ return dataUrl; } }
window.registerSecure = async function(){
  var name=el('regName').value.trim(), email=el('regEmail').value.trim(), phone=cleanPhone(el('regPhone').value), pass=el('regPass').value.trim();
  var role=document.querySelector('input[name="regRole"]:checked').value; var err=el('authErrorMsg'); err.innerText='';
  if(!name) return err.innerText='❌ اكتب اسمك'; if(!email||email.indexOf('@')===-1) return err.innerText='❌ اكتب بريد صحيح'; if(phone.length!==11) return err.innerText='❌ الرقم 11 رقم'; if(!pass||pass.length<6) return err.innerText='❌ كلمة المرور 6+';
  var users=getUsers(); if(users.find(function(x){ return x.phone===phone; })) return err.innerText='❌ الرقم متسجل - سجل دخول';
  var docs=null, vehicle=null;
  if(role==='captain'){ docs=getCaptainDocsFromForm(); vehicle={type:el('capVehicleType').value,model:el('capVehicleModel').value.trim(),year:el('capVehicleYear').value.trim(),color:el('capVehicleColor').value.trim(),plate:el('capPlateNumber').value.trim(),chassis:el('capChassisNumber').value.trim()}; var ve=validateCaptainDocs(docs,vehicle); if(ve){ err.innerText='❌ '+ve; alert('❌ '+ve); return; } }
  try{
    var cred=await fbAuth.createUserWithEmailAndPassword(email,pass);
    var uid=cred.user.uid;
    var referral=el('regReferral').value.trim();
    var nu={id:uid,name:name,email:email,phone:phone,role:role,active:true,authMethod:'email',wallet:referral?20:0,createdAt:new Date().toISOString(),captainStatus:role==='captain'?'pending':null,captainRejectReason:'',captainDocs:docs,vehicle:vehicle};
    if(role==='captain' && docs){ for(var k in docs){ if(docs[k] && docs[k].indexOf('data:')===0) docs[k]=await uploadToFirebase(docs[k],'captains/'+uid+'/'+k); } nu.captainDocs=docs; }
    var toLocal={}; for(var kk in nu) toLocal[kk]=nu[kk]; toLocal.pass='__AUTH_ONLY__'; users.push(toLocal); saveUsers(users);
    fbSet('users/'+uid, nu);
    if(role==='captain') fbSet('captainRequests/'+uid,{id:uid,name:name,phone:phone,captainStatus:'pending',captainDocs:docs,vehicle:vehicle});
    if(referral) DB.customerWallet=20;
    captainDocsData={};
    if(role==='captain'){ alert('✅ تم استلام طلبك! مستنداتك وصلت للأدمن'); window.switchAuthTab('login'); return; }
    window.setSession(nu); alert('🎉 أهلاً بيك يا '+name); window.navigate('customer');
  }catch(e){ err.innerText='❌ '+e.message; alert('❌ '+(e.code==='auth/email-already-in-use'?'البريد ده متسجل قبل كده':e.message)); }
};
window.loginSecure = async function(){
  var email=el('authEmailInput').value.trim(), pass=el('authPassInput').value.trim(), err=el('authErrorMsg'); err.innerText='';
  if(!email||email.indexOf('@')===-1) return err.innerText='❌ اكتب البريد اللي سجلت بيه';
  if(!pass) return err.innerText='❌ اكتب كلمة المرور';
  try{
    var cred=await fbAuth.signInWithEmailAndPassword(email,pass);
    var snap=await fbDB.ref('users/'+cred.user.uid).once('value'); var u=snap.val();
    if(!u){ u=getUsers().find(function(x){ return x.email===email; }); if(!u) return err.innerText='❌ حسابك مش موجود - سجل من جديد'; }
    if(u.active===false) return err.innerText='🚫 حسابك محظور';
    if(u.role==='captain'){
      if(u.captainStatus==='pending'){ err.innerText='⏳ طلبك تحت المراجعة'; alert('⏳ طلبك لسه تحت المراجعة'); return; }
      if(u.captainStatus==='rejected'){ var reason=u.captainRejectReason||'بدون سبب'; err.innerText='❌ اترفض: '+reason; if(confirm('❌ اترفض\nالسبب: '+reason+'\nعايز تعدل مستنداتك؟')){ window.switchAuthTab('register'); document.querySelector('input[name="regRole"][value="captain"]').checked=true; window.toggleCaptainDocs(true); el('regName').value=u.name; el('regEmail').value=u.email; el('regPhone').value=u.phone; } return; }
    }
    window.setSession(u); if(u.role==='admin'||u.role==='super_admin') window.navigate('admin'); else if(u.role==='captain'){ alert('🚕 أهلاً يا كابتن '+u.name); window.navigate('driver'); } else { DB.customerWallet=u.wallet||0; window.navigate('customer'); }
  }catch(e){ err.innerText='❌ '+(e.code==='auth/wrong-password'?'كلمة المرور غلط':e.code==='auth/user-not-found'?'البريد مش متسجل':e.message); }
};
window.loginWithGoogle = async function(){ try{ var p=new firebase.auth.GoogleAuthProvider(); var res=await fbAuth.signInWithPopup(p); var fu=res.user; var snap=await fbDB.ref('users/'+fu.uid).once('value'); var u=snap.val(); if(!u){ u={id:fu.uid,name:fu.displayName||fu.email.split('@')[0],email:fu.email,phone:'',role:'customer',active:true,authMethod:'google',wallet:0,createdAt:new Date().toISOString()}; fbSet('users/'+fu.uid,u); var users=getUsers(); var lc={}; for(var k in u) lc[k]=u[k]; lc.pass='__AUTH_ONLY__'; users.push(lc); saveUsers(users); } window.setSession(u); window.navigate('customer'); }catch(e){ alert('❌ جوجل: '+e.message); } };
window.getSurgeMultiplier = function(){ var h=new Date().getHours(); var isPeak=(h>=7 && h<=9)||(h>=17 && h<=20)||(h>=22||h<=1); if(localStorage.getItem('TAWSILA_SURGE_MANUAL')==='on') return 1.5; if(isPeak) return 1.3; return 1.0; };
window.toggleSurgeManual = function(){ var cur=localStorage.getItem('TAWSILA_SURGE_MANUAL')==='on'; localStorage.setItem('TAWSILA_SURGE_MANUAL',cur?'off':'on'); alert(cur?'❌ الذروة اتقفلت':'🔥 الذروة اشتغلت x1.5'); window.recalcTrip(); };
window.recalcTrip = function(){ var base=25; var v=el('vehicleSelect').value; if(v==='توكتوك') base=15; else if(v==='موتوسيكل') base=20; var mult=window.getSurgeMultiplier(); var total=base*mult; if(el('calcTotalFareText')) el('calcTotalFareText').innerText=total.toFixed(2)+' ج.م'+(mult>1?' 🔥 ذروة x'+mult:''); var b=el('surgeBadge'); if(b){ if(mult>1){ b.classList.remove('hidden'); b.innerText='🔥 وقت ذروة - السعر زاد x'+mult; } else b.classList.add('hidden'); } activeTripData={from:el('pickupInput').value,to:el('dropoffInput').value,vehicle:v,fare:total}; return total; };
window.requestTrip = function(){ var fare=window.recalcTrip(); if(DB.customerWallet<fare){ alert('❌ رصيدك مش كفاية - اشحن الأول'); window.openWalletModal(); return; } alert('✅ تم إرسال طلبك للكباتن!\nمن: '+activeTripData.from+'\nلـ: '+activeTripData.to+'\nالأجرة: '+fare+' ج'); var cur=safeParse('TAWSILA_SESSION',{}); fbPush('trips',{from:activeTripData.from,to:activeTripData.to,vehicle:activeTripData.vehicle,fare:fare,user:cur.name||'ضيف',userUid:cur.id||'',status:'pending',at:new Date().toISOString()}); var tx=safeParse('TAWSILA_TX',[]); tx.push({type:'trip',amount:fare,time:new Date().toLocaleString('ar-EG')}); saveLS('TAWSILA_TX',tx); saveLS('TAWSILA_LAST_TRIP',activeTripData); window.sendPush('رحلة جديدة','من '+activeTripData.from); };
window.requestPackageDelivery = function(){ var from=prompt('من فين؟'); if(!from) return; var to=prompt('لفين؟'); if(!to) return; var w=prompt('الوزن؟','2'); if(!w) return; var fee=15+parseFloat(w)*3; if(!confirm('📦 شحنة من: '+from+' لـ: '+to+'\nالتكلفة: '+fee.toFixed(2)+' ج\nمتأكد؟')) return; fbPush('packages',{from:from,to:to,weight:w,fee:fee,status:'pending',at:new Date().toISOString()}); alert('✅ تم إرسال طلب الشحنة'); };
window.scheduleTrip = function(){ var d=prompt('تاريخ (2026-11-13):'); if(!d) return; var t=prompt('الوقت (07:00):'); if(!t) return; var list=safeParse('TAWSILA_SCHEDULED',[]); list.push({date:d,time:t,from:el('pickupInput').value,to:el('dropoffInput').value}); saveLS('TAWSILA_SCHEDULED',list); alert('✅ اتجدولت: '+d+' - '+t); };
window.sendTripChat = function(){ var inp=el('tripChatInput'); if(!inp.value.trim()) return; var msgs=safeParse('TAWSILA_TRIP_CHAT',[]); var cur=safeParse('TAWSILA_SESSION',{}); msgs.push({from:cur.name||'أنا',text:inp.value.trim(),at:new Date().toLocaleTimeString('ar-EG')}); saveLS('TAWSILA_TRIP_CHAT',msgs); inp.value=''; window.renderTripChat(); };
window.renderTripChat = function(){ var box=el('tripChatBox'); if(!box) return; var msgs=safeParse('TAWSILA_TRIP_CHAT',[]); box.innerHTML=msgs.map(function(m){ return '<div style="background:#f1f5f9;padding:8px;border-radius:10px;margin-top:4px"><b>'+m.from+':</b> '+m.text+'</div>'; }).join('')||'مفيش رسائل'; };
window.rateCaptain = function(){ var s=prompt('قيّم الكابتن 1-5:','5'); if(!s) return; s=parseInt(s); var r=safeParse('TAWSILA_CAPTAIN_RATINGS',[]); r.push({stars:s,at:new Date().toISOString()}); saveLS('TAWSILA_CAPTAIN_RATINGS',r); var avg=r.reduce(function(a,b){ return a+b.stars; },0)/r.length; alert('⭐ شكراً - متوسط الكابتن: '+avg.toFixed(1)); };
window.sendSOS = function(){ if(!confirm('🚨 متأكد تبعت SOS؟')) return; navigator.geolocation.getCurrentPosition(function(pos){ var cur=safeParse('TAWSILA_SESSION',{}); fbPush('sos',{lat:pos.coords.latitude,lng:pos.coords.longitude,user:cur.name||'ضيف',userUid:cur.id||'',at:new Date().toISOString()}); alert('🚨 تم إرسال SOS'); window.open('tel:122'); },function(){ alert('شغّل GPS'); }); };
window.setCaptainShift = function(s){ localStorage.setItem('TAWSILA_CAPTAIN_SHIFT',s); if(el('captainShiftLabel')) el('captainShiftLabel').innerText='شيفتك: '+s; var cur=safeParse('TAWSILA_SESSION',null); if(cur) fbUpdate('users/'+cur.id,{shift:s}); alert('✅ شيفتك: '+s); };
window.startCaptainGPS = function(){ if(!navigator.geolocation) return alert('جهازك مش بيدعم GPS'); navigator.geolocation.watchPosition(function(pos){ var cur=safeParse('TAWSILA_SESSION',null); if(cur) fbSet('captainLocations/'+cur.id,{lat:pos.coords.latitude,lng:pos.coords.longitude,name:cur.name,at:Date.now()}); },null,{enableHighAccuracy:true,maximumAge:3000}); alert('✅ GPS اتفعل'); };
window.simulateIncomingTrip = function(){ var trip={from:'الثقافة',to:'الكورنيش',fare:25}; if(el('captainOfferBox')){ el('captainOfferBox').classList.remove('hidden'); el('captainOfferBox').innerHTML='<b>🔔 رحلة جديدة!</b><br>من: '+trip.from+' - لـ: '+trip.to+' - '+trip.fare+' ج<br><button onclick="acceptTrip()" style="background:#059669;color:#fff;padding:6px 12px;border-radius:8px;margin-top:6px;font-weight:900;border:none">✅ قبول</button>'; } window.sendPush('🔔 رحلة جديدة يا كابتن!','من: '+trip.from); };
window.acceptTrip = function(){ alert('✅ قبلت الرحلة'); if(el('captainOfferBox')) el('captainOfferBox').classList.add('hidden'); };
window.captainCompleteTrip = function(){ captainTodayTripsCount++; DB.captainWallet=(DB.captainWallet||0)+25; if(el('captainTripsTxt')) el('captainTripsTxt').innerText=captainTodayTripsCount; if(el('captainWalletTxt')) el('captainWalletTxt').innerText=DB.captainWallet+' ج'; var bonus=0; if(captainTodayTripsCount===10) bonus=50; if(captainTodayTripsCount===20) bonus=120; if(bonus>0){ DB.captainWallet+=bonus; alert('🎉 بونص '+bonus+' ج'); } if(el('captainBonusBox')) el('captainBonusBox').innerText='🎁 رحلات اليوم: '+captainTodayTripsCount+' / 20 - '+(captainTodayTripsCount/20*100).toFixed(0)+'%'; alert('✅ الرحلة خلصت'); };
function getDepositMethods(){ var m=safeParse('TAWSILA_DEPOSIT_METHODS',null); if(!m){ m=[{id:'dep1',name:'فودافون كاش',account:'01000000000',enabled:true},{id:'dep2',name:'انستاباي',account:'01000000000',enabled:true}]; saveLS('TAWSILA_DEPOSIT_METHODS',m); } return m; }
window.openWalletModal = function(){ if(el('realPayBalance')) el('realPayBalance').innerText=(DB.customerWallet||0).toFixed(2)+' ج.م'; var methods=getDepositMethods().filter(function(x){ return x.enabled; }); if(el('realPayMethodsList')) el('realPayMethodsList').innerHTML=methods.map(function(mm,i){ return '<label id="deposit-card-'+mm.id+'" onclick="selectDepositMethod(\''+mm.id+'\')" style="display:flex;justify-content:space-between;padding:12px;border:2px solid '+(i===0?'#059669':'#e2e8f0')+';border-radius:12px;cursor:pointer;margin-top:6px"><span>'+mm.name+'</span><span style="font-family:monospace;font-weight:bold">'+mm.account+'</span></label>'; }).join(''); if(methods.length) _depositSelectedMethod=methods[0].id; _depositProofImg=''; if(el('realPayProofInput')) el('realPayProofInput').value=''; if(el('depositProofPreview')) el('depositProofPreview').classList.add('hidden'); window.updateRealPaySummary(); window.renderMyDepositRequests(); if(methods.length) window.selectDepositMethod(methods[0].id); if(el('realPayModal')) el('realPayModal').classList.remove('hidden'); };
window.closeRealPayModal = function(){ if(el('realPayModal')) el('realPayModal').classList.add('hidden'); };
window.setRealPayAmount = function(v){ if(el('realPayAmount')) el('realPayAmount').value=v; window.updateRealPaySummary(); };
window.selectDepositMethod = function(id){ _depositSelectedMethod=id; var mm=getDepositMethods().find(function(x){ return x.id===id; }); var box=el('depositPayDetails'); if(box){ box.classList.remove('hidden'); box.innerHTML='<div style="background:#0f172a;color:#fff;padding:12px;border-radius:12px;text-align:center">حوّل على: <b>'+mm.name+'</b><p style="font-family:monospace;color:#fbbf24;font-size:18px;font-weight:900" id="depositTargetAccount">'+mm.account+'</p><button onclick="copyDepositAccount()" style="background:#fbbf24;color:#111;padding:6px 12px;border-radius:8px;font-weight:900;border:none">📋 انسخ الرقم</button></div>'; } window.updateRealPaySummary(); };
window.copyDepositAccount = function(){ var acc=el('depositTargetAccount').innerText; navigator.clipboard.writeText(acc).then(function(){ alert('✅ اتنسخ: '+acc); }); };
window.updateRealPaySummary = function(){ var amt=parseFloat(el('realPayAmount')?el('realPayAmount').value:0)||0; var mm=getDepositMethods().find(function(x){ return x.id===_depositSelectedMethod; }); if(el('realPaySummary')) el('realPaySummary').innerHTML='هتحول: <b>'+amt+' ج</b> على '+(mm?mm.name+' - '+mm.account:'')+'<br>هيتضاف بعد الموافقة: <b style="color:#34d399">'+amt+' ج</b>'; };
window.previewDepositProof = function(input){ var f=input.files[0]; if(!f) return; if(f.size>3*1024*1024){ alert('❌ الصورة كبيرة'); input.value=''; return; } var r=new FileReader(); r.onload=function(e){ var img=new Image(); img.onload=function(){ var c=document.createElement('canvas'); var sc=Math.min(1,800/img.width); c.width=img.width*sc; c.height=img.height*sc; c.getContext('2d').drawImage(img,0,0,c.width,c.height); _depositProofImg=c.toDataURL('image/jpeg',0.7); var p=el('depositProofPreview'); if(p){ p.src=_depositProofImg; p.classList.remove('hidden'); } if(el('depositProofLabel')) el('depositProofLabel').innerText='✅ تم رفع الإثبات'; }; img.src=e.target.result; }; r.readAsDataURL(f); };
window.submitRealPayRequest = async function(){ var amt=parseFloat(el('realPayAmount').value)||0; var sender=cleanPhone(el('realPaySenderNumber').value); var method=getDepositMethods().find(function(x){ return x.id===_depositSelectedMethod; }); if(amt<10) return alert('❌ الحد الأدنى 10 ج'); if(!method) return alert('❌ اختار طريقة'); if(sender.length!==11) return alert('❌ اكتب الرقم اللي حولت منه'); if(!_depositProofImg) return alert('❌ لازم صورة إثبات'); var h=window.hashImage(_depositProofImg); var all=safeParse('TAWSILA_DEPOSIT_REQUESTS',[]); if(all.find(function(r){ return r.proofHash===h; })) return alert('❌ الصورة دي اتبعتت قبل كده!'); var cur=safeParse('TAWSILA_SESSION',null); var proofUrl=await uploadToFirebase(_depositProofImg,'deposits/'+Date.now()); var req={id:'DEP-'+Date.now(),userId:cur?cur.id:'guest',userUid:cur?cur.id:'',userName:cur?cur.name:'ضيف',userPhone:cur?cur.phone:'',amount:amt,methodId:method.id,methodName:method.name,methodAccount:method.account,senderNumber:sender,proofImg:proofUrl,proofHash:h,status:'pending',rejectReason:'',createdAt:new Date().toISOString(),createdAtTxt:new Date().toLocaleString('ar-EG')}; all.push(req); saveLS('TAWSILA_DEPOSIT_REQUESTS',all); fbSet('depositRequests/'+req.id,req); _depositProofImg=''; if(el('realPaySenderNumber')) el('realPaySenderNumber').value=''; window.closeRealPayModal(); alert('✅ تم إرسال طلب الشحن للأدمن - '+amt+' ج'); window.renderMyDepositRequests(); };
window.renderMyDepositRequests = function(){ var cur=safeParse('TAWSILA_SESSION',null); var all=safeParse('TAWSILA_DEPOSIT_REQUESTS',[]); var mine=all.filter(function(r){ return !cur||r.userId===cur.id||r.userPhone===cur.phone; }).slice(-5).reverse(); var box=el('myDepositRequestsList'); if(!box) return; box.innerHTML=mine.map(function(r){ var st=r.status==='approved'?'✅ تمت الموافقة':r.status==='rejected'?'❌ اترفض: '+(r.rejectReason||''): '⏳ تحت المراجعة'; return '<div style="padding:8px;border-radius:10px;border:1px solid #e2e8f0;background:#f8fafc;display:flex;justify-content:space-between;margin-top:4px"><span>'+r.amount+' ج - '+r.methodName+'</span><span style="font-weight:bold">'+st+'</span></div>'; }).join('')||'مفيش طلبات'; };
window.switchAdminSubTab = function(t){ var tabs=['depositRequests','captainRequests','users','trips']; for(var i=0;i<tabs.length;i++){ if(el('admin-subtab-'+tabs[i])) el('admin-subtab-'+tabs[i]).classList.add('hidden'); } if(el('admin-subtab-'+t)) el('admin-subtab-'+t).classList.remove('hidden'); if(t==='depositRequests') window.renderDepositRequests(); if(t==='captainRequests') window.renderCaptainRequests(); if(t==='users') window.renderAdminUsers(); if(t==='trips') window.renderAdminTrips(); };
window.filterDepositRequests = function(f){ _depositFilter=f; window.renderDepositRequests(); };
window.renderDepositRequests = function(){ var all=safeParse('TAWSILA_DEPOSIT_REQUESTS',[]); var pending=all.filter(function(r){ return r.status==='pending'; }); if(el('pendingDepositsTxt')) el('pendingDepositsTxt').innerText=pending.length+' معلق'; var badge=el('pendingDepositsBadge'); if(badge){ badge.innerText=pending.length; badge.classList.toggle('hidden',pending.length===0); } var list=all.filter(function(r){ return _depositFilter==='all'?true:r.status===_depositFilter; }).slice().reverse(); if(el('depositRequestsList')) el('depositRequestsList').innerHTML=list.map(function(r){ return '<div style="border:1px solid #e2e8f0;border-radius:12px;padding:12px;background:#f8fafc;margin-top:8px"><div style="display:flex;justify-content:space-between"><div><b>'+r.userName+'</b> - '+r.userPhone+'<br><span>'+(r.status==='approved'?'✅ مقبول':r.status==='rejected'?'❌ مرفوض':'⏳ معلق')+'</span> - '+(r.createdAtTxt||'')+'</div><div><b>'+r.amount+' ج</b><div>'+r.methodName+'</div></div></div><div style="background:#fff;border:1px solid #e2e8f0;padding:8px;border-radius:8px;margin-top:6px">📱 المرسل منه: <b style="font-family:monospace">'+r.senderNumber+'</b></div><div style="display:flex;gap:6px;margin-top:8px"><button onclick="viewDepositProof(\''+r.id+'\')" style="flex:1;background:#2563eb;color:#fff;font-weight:900;padding:8px;border-radius:10px;border:none">📸 عرض الإثبات</button>'+(r.status==='pending'?'<button onclick="approveDepositRequest(\''+r.id+'\')" style="flex:1;background:#059669;color:#fff;font-weight:900;padding:8px;border-radius:10px;border:none">✅ موافقة</button><button onclick="rejectDepositRequest(\''+r.id+'\')" style="flex:1;background:#e11d48;color:#fff;font-weight:900;padding:8px;border-radius:10px;border:none">❌ رفض</button>':'')+'</div></div>'; }).join('')||'مفيش طلبات'; };
window.viewDepositProof = function(id){ var r=safeParse('TAWSILA_DEPOSIT_REQUESTS',[]).find(function(x){ return x.id===id; }); if(!r) return; if(el('depositProofModalTitle')) el('depositProofModalTitle').innerText='إثبات - '+r.userName+' - '+r.amount+' ج'; if(el('depositProofModalImg')) el('depositProofModalImg').src=r.proofImg||''; if(el('depositProofModalInfo')) el('depositProofModalInfo').innerHTML='<p><b>العميل:</b> '+r.userName+' - '+r.userPhone+'</p><p><b>المبلغ:</b> '+r.amount+' ج</p><p><b>المرسل منه:</b> '+r.senderNumber+'</p><p><b>على:</b> '+r.methodName+' - '+r.methodAccount+'</p>'; if(el('depositProofApproveBtn')) el('depositProofApproveBtn').setAttribute('onclick',"approveDepositRequest('"+r.id+"'); closeDepositProofModal();"); if(el('depositProofRejectBtn')) el('depositProofRejectBtn').setAttribute('onclick',"closeDepositProofModal(); rejectDepositRequest('"+r.id+"');"); if(el('depositProofModal')) el('depositProofModal').classList.remove('hidden'); };
window.closeDepositProofModal = function(){ if(el('depositProofModal')) el('depositProofModal').classList.add('hidden'); };
window.approveDepositRequest = function(id){ var list=safeParse('TAWSILA_DEPOSIT_REQUESTS',[]); var r=list.find(function(x){ return x.id===id; }); if(!r||r.status!=='pending') return alert('اتراجع قبل كده'); if(!confirm('توافق على شحن '+r.amount+' ج لـ '+r.userName+'؟')) return; r.status='approved'; saveLS('TAWSILA_DEPOSIT_REQUESTS',list); fbUpdate('depositRequests/'+id,{status:'approved'}); var users=getUsers(); var u=null; for(var i=0;i<users.length;i++){ if(users[i].id===r.userId||users[i].phone===r.userPhone) u=users[i]; } if(u){ u.wallet=(u.wallet||0)+r.amount; saveUsers(users); fbUpdate('users/'+u.id,{wallet:u.wallet}); } var cur=safeParse('TAWSILA_SESSION',null); if(cur && (cur.id===r.userId||cur.phone===r.userPhone)){ DB.customerWallet+=r.amount; window.updateWalletUI(); } var tx=safeParse('TAWSILA_TX',[]); tx.push({type:'deposit',amount:r.amount,time:new Date().toLocaleString('ar-EG')}); saveLS('TAWSILA_TX',tx); window.renderDepositRequests(); alert('✅ تم قبول الشحن'); };
window.rejectDepositRequest = function(id){ var list=safeParse('TAWSILA_DEPOSIT_REQUESTS',[]); var r=list.find(function(x){ return x.id===id; }); if(!r||r.status!=='pending') return; var reason=prompt('سبب الرفض:'); if(!reason) return; reason=reason.trim(); if(!reason) return alert('لازم تكتب السبب'); r.status='rejected'; r.rejectReason=reason; saveLS('TAWSILA_DEPOSIT_REQUESTS',list); fbUpdate('depositRequests/'+id,{status:'rejected',rejectReason:reason}); window.renderDepositRequests(); alert('❌ تم الرفض'); };
window.filterCaptainRequests = function(f){ _captainFilter=f; window.renderCaptainRequests(); };
window.renderCaptainRequests = function(){ var users=getUsers().filter(function(u){ return u.role==='captain'; }); var pending=users.filter(function(u){ return u.captainStatus==='pending'; }); if(el('pendingCountTxt')) el('pendingCountTxt').innerText=pending.length+' معلق'; var badge=el('pendingCaptainsBadge'); if(badge){ badge.innerText=pending.length; badge.classList.toggle('hidden',pending.length===0); } var list=users.filter(function(u){ if(_captainFilter==='all') return true; if(_captainFilter==='pending') return u.captainStatus==='pending'||!u.captainStatus; return u.captainStatus===_captainFilter; }); if(el('captainRequestsList')) el('captainRequestsList').innerHTML=list.map(function(u){ var v=u.vehicle||{}; var st=u.captainStatus||'pending'; return '<div style="border:1px solid #e2e8f0;border-radius:12px;padding:12px;background:#f8fafc;margin-top:8px"><div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px"><div><b>'+u.name+'</b> - '+u.phone+'<br><span>'+(st==='approved'?'✅ مقبول':st==='rejected'?'❌ مرفوض':'⏳ معلق')+'</span></div><div style="display:flex;gap:6px"><button onclick="viewCaptainDocs(\''+u.id+'\')" style="background:#2563eb;color:#fff;padding:6px 10px;border-radius:8px;font-weight:bold;border:none">📸 مستندات</button>'+(st!=='approved'?'<button onclick="approveCaptain(\''+u.id+'\')" style="background:#059669;color:#fff;padding:6px 10px;border-radius:8px;font-weight:bold;border:none">✅ موافقة</button>':'')+(st!=='rejected'?'<button onclick="rejectCaptain(\''+u.id+'\')" style="background:#e11d48;color:#fff;padding:6px 10px;border-radius:8px;font-weight:bold;border:none">❌ رفض</button>':'')+'</div></div><div style="background:#fff;border:1px solid #e2e8f0;padding:8px;border-radius:8px;margin-top:6px">🚗 '+(v.type||'-')+' - '+(v.model||'-')+' - '+(v.year||'-')+' - '+(v.color||'-')+' - '+(v.plate||'-')+' - '+(v.chassis||'-')+'</div>'+(st==='rejected' && u.captainRejectReason?'<p style="color:#e11d48;background:#fff1f2;padding:8px;border-radius:8px;margin-top:6px">❌ '+u.captainRejectReason+'</p>':'')+'</div>'; }).join('')||'مفيش طلبات'; };
window.viewCaptainDocs = function(id){ var u=null; var users=getUsers(); for(var i=0;i<users.length;i++){ if(users[i].id===id) u=users[i]; } if(!u) return; var d=u.captainDocs||{}; var v=u.vehicle||{}; var img=function(l,s){ return '<div><p style="font-weight:bold">'+l+'</p>'+(s?'<img src="'+s+'" style="width:100%;height:160px;object-fit:cover;border-radius:12px;border:1px solid #ddd;cursor:pointer" onclick="window.open(this.src,\'_blank\')">':'<p style="color:#e11d48">❌ مش مرفوعة</p>')+'</div>'; }; if(el('docsModalTitle')) el('docsModalTitle').innerText='مستندات: '+u.name+' - '+u.phone; if(el('docsModalBody')) el('docsModalBody').innerHTML='<div style="background:#fef3c7;border:1px solid #f59e0b;padding:8px;border-radius:10px">🚗 '+(v.type||'-')+' - '+(v.model||'-')+' - '+(v.year||'-')+' - '+(v.color||'-')+' - '+(v.plate||'-')+' - '+(v.chassis||'-')+'</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px">'+img('🪪 البطاقة وش',d.idFront)+img('🪪 البطاقة ضهر',d.idBack)+img('🚗 رخصة المركبة وش',d.vehicleFront)+img('🚗 رخصة المركبة ضهر',d.vehicleBack)+img('🪪 رخصة القيادة وش',d.driveFront)+img('🪪 رخصة القيادة ضهر',d.driveBack)+'</div><div style="display:flex;gap:8px;margin-top:8px"><button onclick="approveCaptain(\''+u.id+'\'); closeCaptainDocsModal();" style="flex:1;background:#059669;color:#fff;font-weight:900;padding:10px;border-radius:12px;border:none">✅ موافقة</button><button onclick="closeCaptainDocsModal(); rejectCaptain(\''+u.id+'\');" style="flex:1;background:#e11d48;color:#fff;font-weight:900;padding:10px;border-radius:12px;border:none">❌ رفض</button></div>'; if(el('captainDocsModal')) el('captainDocsModal').classList.remove('hidden'); };
window.closeCaptainDocsModal = function(){ if(el('captainDocsModal')) el('captainDocsModal').classList.add('hidden'); };
window.approveCaptain = function(id){ var users=getUsers(); var u=null; for(var i=0;i<users.length;i++){ if(users[i].id===id) u=users[i]; } if(!u) return; if(!confirm('توافق على الكابتن '+u.name+'؟')) return; u.captainStatus='approved'; u.captainRejectReason=''; u.active=true; saveUsers(users); fbUpdate('users/'+id,{captainStatus:'approved'}); fbUpdate('captainRequests/'+id,{captainStatus:'approved'}); window.renderCaptainRequests(); window.renderAdminUsers(); alert('✅ تم قبول الكابتن'); };
window.rejectCaptain = function(id){ var users=getUsers(); var u=null; for(var i=0;i<users.length;i++){ if(users[i].id===id) u=users[i]; } if(!u) return; var reason=prompt('سبب رفض الكابتن '+u.name+':'); if(!reason) return; reason=reason.trim(); if(!reason) return alert('لازم تكتب السبب'); u.captainStatus='rejected'; u.captainRejectReason=reason; saveUsers(users); fbUpdate('users/'+id,{captainStatus:'rejected',captainRejectReason:reason}); fbUpdate('captainRequests/'+id,{captainStatus:'rejected',captainRejectReason:reason}); window.renderCaptainRequests(); alert('❌ تم الرفض'); };
window.renderAdminUsers = function(){ var q=(el('adminSearchUser')?el('adminSearchUser').value.toLowerCase():''); var users=getUsers().filter(function(u){ return !q||u.name.toLowerCase().indexOf(q)>-1||u.phone.indexOf(q)>-1; }); if(el('adminUsersList')) el('adminUsersList').innerHTML=users.map(function(u){ return '<div style="display:flex;justify-content:space-between;border:1px solid #e2e8f0;padding:8px;border-radius:10px;margin-top:6px;flex-wrap:wrap;gap:6px"><span><b>'+u.name+'</b> - '+u.phone+' - '+u.role+' - رصيد: '+(u.wallet||0)+' ج - '+(u.active===false?'🚫 محظور':'✅ نشط')+'</span><div style="display:flex;gap:6px"><button onclick="toggleBlockUser(\''+u.id+'\')" style="background:#e11d48;color:#fff;padding:6px 10px;border-radius:8px;font-weight:bold;border:none">'+(u.active===false?'فك حظر':'حظر')+'</button><button onclick="makeUserAdmin(\''+u.id+'\')" style="background:#7c3aed;color:#fff;padding:6px 10px;border-radius:8px;font-weight:bold;border:none">👑 أدمن</button><button onclick="addBalanceToUser(\''+u.id+'\')" style="background:#059669;color:#fff;padding:6px 10px;border-radius:8px;font-weight:bold;border:none">💰 + رصيد</button></div></div>'; }).join('')||'مفيش'; };
window.toggleBlockUser = function(id){ var users=getUsers(); var u=null; for(var i=0;i<users.length;i++){ if(users[i].id===id) u=users[i]; } if(!u) return; u.active=(u.active===false); saveUsers(users); fbUpdate('users/'+id,{active:u.active}); window.renderAdminUsers(); };
window.makeUserAdmin = function(id){ if(!confirm('تخلي المستخدم ده أدمن؟')) return; var users=getUsers(); var u=null; for(var i=0;i<users.length;i++){ if(users[i].id===id) u=users[i]; } u.role='admin'; saveUsers(users); fbUpdate('users/'+id,{role:'admin'}); fbSet('admins/'+id,{role:'admin',at:new Date().toISOString()}); alert('✅ بقى أدمن'); window.renderAdminUsers(); };
window.addBalanceToUser = function(id){ var amt=parseFloat(prompt('المبلغ؟','50')); if(!amt) return; var users=getUsers(); var u=null; for(var i=0;i<users.length;i++){ if(users[i].id===id) u=users[i]; } u.wallet=(u.wallet||0)+amt; saveUsers(users); fbUpdate('users/'+id,{wallet:u.wallet}); alert('✅ اتضاف '+amt+' ج'); window.renderAdminUsers(); };
window.renderAdminTrips = function(){ fbDB.ref('trips').once('value').then(function(s){ var v=s.val()||{}; var list=Object.values(v).slice(-20).reverse(); if(el('adminTripsList')) el('adminTripsList').innerHTML=list.map(function(t){ return '<div style="border:1px solid #e2e8f0;padding:8px;border-radius:10px;margin-top:6px">🚕 '+(t.user||'')+' - '+(t.from||'')+' → '+(t.to||'')+' - '+(t.fare||0)+' ج</div>'; }).join('')||'مفيش رحلات'; }); };
window.renderProfitDashboard = function(){ var tx=safeParse('TAWSILA_TX',[]); var trips=tx.filter(function(t){ return t.type==='trip'; }); var deps=tx.filter(function(t){ return t.type==='deposit'; }); var total=trips.reduce(function(a,b){ return a+(b.amount||0); },0); var comm=total*0.10; var depTotal=deps.reduce(function(a,b){ return a+(b.amount||0); },0); if(el('profitDashboard')) el('profitDashboard').innerHTML='<h3>📊 أرباح التطبيق</h3><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px;text-align:center"><div style="background:#ecfdf5;border:1px solid #a7f3d0;padding:10px;border-radius:12px">رحلات<div style="font-weight:900">'+trips.length+'</div></div><div style="background:#eff6ff;border:1px solid #bfdbfe;padding:10px;border-radius:12px">إجمالي<div style="font-weight:900">'+total.toFixed(0)+' ج</div></div><div style="background:#fef3c7;border:1px solid #fde68a;padding:10px;border-radius:12px">عمولة 10%<div style="font-weight:900;color:#d97706">'+comm.toFixed(0)+' ج</div></div><div style="background:#f5f3ff;border:1px solid #ddd6fe;padding:10px;border-radius:12px">شحن<div style="font-weight:900">'+depTotal.toFixed(0)+' ج</div></div></div><button onclick="exportProfitExcel()" style="background:#059669;color:#fff;padding:8px 12px;border-radius:10px;font-weight:bold;margin-top:8px;border:none">📥 تصدير Excel</button>'; };
window.exportProfitExcel = function(){ var tx=safeParse('TAWSILA_TX',[]); var csv='النوع,المبلغ,التاريخ\n'+tx.map(function(t){ return (t.type||'')+','+(t.amount||0)+','+(t.time||''); }).join('\n'); var blob=new Blob(['\ufeff'+csv],{type:'text/csv'}); var a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='tawsila-report.csv'; a.click(); };
window.exportAllUsers = function(){ var users=getUsers(); var csv='الاسم,الهاتف,الدور,الرصيد\n'+users.map(function(u){ return (u.name||'')+','+(u.phone||'')+','+(u.role||'')+','+(u.wallet||0); }).join('\n'); var blob=new Blob(['\ufeff'+csv],{type:'text/csv'}); var a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='tawsila-users.csv'; a.click(); alert('✅ نزل ملف المستخدمين'); };
window.clearFakeData = function(){ if(!confirm('تمسح البيانات التجريبية؟')) return; localStorage.removeItem('TAWSILA_SCHEDULED'); localStorage.removeItem('TAWSILA_TRIP_CHAT'); alert('✅ اتمسحت'); };
window.viewComplaints = function(){ var list=safeParse('TAWSILA_COMPLAINTS',[]); alert(list.length?('📩 الشكاوى:\n\n'+list.map(function(c){ return '- '+c.text; }).join('\n')):'مفيش شكاوى'); };
window.viewSOSList = function(){ fbDB.ref('sos').once('value').then(function(s){ var v=s.val()||{}; var list=Object.values(v); alert(list.length?('🚨 SOS:\n\n'+list.map(function(x){ return '- '+(x.user||'')+' - '+x.lat+','+x.lng; }).join('\n')):'مفيش SOS'); }); };
window.getMyReferralCode = function(){ var cur=safeParse('TAWSILA_SESSION',null); if(!cur) return '-'; return 'SOHAG-'+(cur.phone||'').slice(-4)+'-'+cur.id.slice(-4).toUpperCase(); };
window.copyReferral = function(){ var c=window.getMyReferralCode(); navigator.clipboard.writeText(c).then(function(){ alert('✅ اتنسخ: '+c); }); };
window.applyReferralCode = function(){ if(localStorage.getItem('TAWSILA_REFERRAL_USED')) return alert('استخدمت كود قبل كده'); var code=prompt('اكتب كود الدعوة:'); if(!code) return; localStorage.setItem('TAWSILA_REFERRAL_USED',code); DB.customerWallet+=20; window.updateWalletUI(); alert('🎉 خدت 20 ج'); };
window.askAssistant = function(){ var q=prompt('🤖 اسأل المساعد:\n- عايز اروح الجامعة\n- بكام المشوار؟\n- عندي شكوى\n- عايز اشحن'); if(!q) return; q=q.toLowerCase(); if(q.indexOf('جامعة')>-1||q.indexOf('كوامل')>-1){ el('dropoffInput').value='جامعة سوهاج - الكوامل'; window.recalcTrip(); alert('🤖 حطيت الوجهة: جامعة سوهاج'); } else if(q.indexOf('كام')>-1||q.indexOf('بكام')>-1) alert('🤖 الثقافة للكورنيش ~25 ج سيارة - 15 ج توكتوك'); else if(q.indexOf('شكوى')>-1){ var comp=prompt('اكتب شكواك:'); if(comp){ var l=safeParse('TAWSILA_COMPLAINTS',[]); l.push({text:comp,at:new Date().toISOString()}); saveLS('TAWSILA_COMPLAINTS',l); alert('✅ شكواك وصلت'); } } else if(q.indexOf('شحن')>-1) alert('🤖 دوس شحن + - اختار طريقة - حول - ارفع صورة'); else alert('🤖 جرب: عايز اروح الجامعة / بكام المشوار / عندي شكوى'); };
window.makeBackup = function(){ var data={}; var keys=['TAWSILA_USERS','TAWSILA_DEPOSIT_REQUESTS','TAWSILA_TX']; for(var i=0;i<keys.length;i++){ try{ data[keys[i]]=JSON.parse(localStorage.getItem(keys[i])||'null'); }catch(e){} } data.backupAt=new Date().toISOString(); var blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}); var a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='tawsila-backup-'+new Date().toISOString().slice(0,10)+'.json'; a.click(); fbPush('backups',{at:new Date().toISOString()}); alert('✅ تم عمل نسخة'); };
window.downloadInvoicePDF = function(){ var trip=safeParse('TAWSILA_LAST_TRIP',{}); var cur=safeParse('TAWSILA_SESSION',{}); var html='<html dir="rtl"><head><meta charset="utf-8"></head><body><h2>🧾 فاتورة - توصيلة سوهاج</h2><p>رقم: INV-'+Date.now()+'</p><p>العميل: '+(cur.name||'ضيف')+'</p><p>من: '+(trip.from||'-')+' - إلى: '+(trip.to||'-')+'</p><p>الأجرة: '+(trip.fare||0)+' ج</p><button onclick="window.print()">🖨️ اطبع / PDF</button></body></html>'; var w=window.open('','_blank'); w.document.write(html); w.document.close(); };

// ===== تشغيل =====
buildUI();
startFirebaseListeners();
var sess = safeParse('TAWSILA_SESSION',null);
if(sess){ if(sess.role==='admin'||sess.role==='super_admin') window.navigate('admin'); else if(sess.role==='captain') window.navigate('driver'); else { DB.customerWallet=sess.wallet||0; window.navigate('customer'); } } else window.navigate('auth');
window.recalcTrip(); window.renderTripChat();
setTimeout(function(){
  try{ if(window.L && el('map')){ var map=L.map('map').setView([26.557,31.694],13); L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png').addTo(map); L.marker([26.557,31.694]).addTo(map).bindPopup('سوهاج'); } }catch(e){}
  try{ if(window.L && el('adminMap')){ var amap=L.map('adminMap').setView([26.557,31.694],13); L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png').addTo(amap); } }catch(e){}
}, 500);